INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('1', 'Jasa Pembuatan Website & Web Application', 'pembuatan-website-aplikasi-web', 'fas fa-globe', 'RECOMMENDED', 'Pengembangan website responsif, company profile, toko online (e-commerce), dan sistem informasi bisnis berbasis Laravel & React.', 'Mulai Dari', 'Rp 2.500.000', '2500000', '/ project', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=800&q=80', 'Kami menyediakan jasa pembuatan website profesional yang dirancang khusus untuk meningkatkan kredibilitas dan penjualan bisnis Anda. Menggunakan teknologi modern terkini dengan desain elegan, SEO-friendly, dan akses super cepat.', '[\"Desain Responsive & Modern\",\"Optimasi SEO & Kecepatan Tinggi\",\"Integrasi Payment Gateway\",\"Gratis Domain & Hosting 1 Tahun\"]', '[\"Free Source Code\",\"Gratis Revisi Desain\",\"Garansi & Support 6 Bulan\",\"Panduan Penggunaan Admin Panel\"]', '[\"Desain Kustom Eksklusif (Non-Template)\",\"Content Management System (CMS) Mudah Digunakan\",\"Integrasi WhatsApp & Live Chat Widget\",\"Keamanan SSL Certificate Terpasang\",\"Analitik Pengunjung (Google Analytics)\"]', 'Halo Elcoding, saya ingin berkonsultasi mengenai Jasa Pembuatan Website & Web Application.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('2', 'Pengembangan Aplikasi Mobile (Android & iOS)', 'pengembangan-aplikasi-mobile', 'fas fa-mobile-alt', 'TERLARIS', 'Aplikasi mobile cross-platform performa tinggi menggunakan Flutter & React Native dengan desain UI/UX interaktif.', 'Mulai Dari', 'Rp 4.500.000', '4500000', '/ project', 'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?auto=format&fit=crop&w=800&q=80', 'Wujudkan ide aplikasi mobile impian Anda untuk Android dan iOS dalam satu codebase efisien. Dilengkapi backend API terstruktur, push notification, serta performa native yang mulus.', '[\"Support Android & iOS\",\"UI\\/UX Interactive & Smooth\",\"Push Notification Realtime\",\"Integrasi API & Cloud DB\"]', '[\"Bantuan Publish ke Google PlayStore & AppStore\",\"Dokumentasi REST API Complete\",\"Free Maintenance 3 Bulan\"]', '[\"Multi-language Support\",\"Fitur Lokasi \\/ GPS Mapping\",\"Sistem Keamanan Auth JWT & Biometric Login\",\"Optimasi Ukuran App & Baterai\"]', 'Halo Elcoding, saya berminat membuat Aplikasi Mobile untuk bisnis saya.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('3', 'Jasa UI/UX Design & Prototyping', 'jasa-ui-ux-design-prototyping', 'fas fa-paint-brush', 'PROMO', 'Perancangan antarmuka pengguna (UI) dan pengalaman pengguna (UX) berbasis penelitian pengguna dan Design System scalable.', 'Mulai Dari', 'Rp 1.200.000', '1200000', '/ project', 'https://images.unsplash.com/photo-1581291518633-83b4ebd1d83e?auto=format&fit=crop&w=800&q=80', 'Layanan pembuatan kraf wireframe, prototype interaktif Figma, serta Design System standar industri untuk mempermudah proses koding tim developer Anda.', '[\"Figma Source File (.fig)\",\"Design System & Component Library\",\"Clickable Interactive Prototype\",\"User Research & Wireframing\"]', '[\"Export Aset SVG\\/PNG\\/JPG\",\"Design Handoff ke Developer\",\"Revisi Sesuai Feedback\"]', '[\"UX Audit & Usability Testing\",\"Responsive Layouts (Desktop & Mobile)\",\"Iconography & Design Palette Custom\"]', 'Halo Elcoding, saya butuh layanan Jasa UI/UX Design untuk aplikasi saya.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('4', 'Private Corporate IT Training', 'private-corporate-it-training', 'fas fa-users-cog', 'SPECIAL', 'Pelatihan teknologi dan pemrograman khusus perusahaan & instansi dengan kurikulum kustom disesuaikan kebutuhan industri Anda.', 'Mulai Dari', 'Rp 3.500.000', '3500000', '/ batch', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=800&q=80', 'Tingkatkan kompetensi digital tim internal perusahaan Anda dalam topik Fullstack Web Development, DevOps, Cloud Infrastructure, atau AI/Data Science bersama instruktur praktisi berpengalaman.', '[\"Kurikulum Custom Sesuai Project Tim\",\"Instruktur Expert Praktisi Industri\",\"Modul & Sertifikat Pelatihan\",\"Konsultasi Studi Kasus Real\"]', '[\"Materi Presentasi & Source Code\",\"Sertifikat Kelulusan Peserta\",\"Evaluasi Hasil Pembelajaran\"]', '[\"Pilihan Metode Onsite atau Online Live Class\",\"Recording Sesi Pelatihan Harian\",\"Group Support Telegram \\/ Slack Dedikasi\"]', 'Halo Elcoding, kami ingin mengadakan Corporate IT Training untuk perusahaan kami.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('5', 'Cloud Server, DevOps & Maintenance', 'cloud-devops-maintenance-server', 'fas fa-server', 'POPULER', 'Konfigurasi cloud server (AWS, GCP, VPS), automasi CI/CD pipeline, monitoring keamanan, dan perawatan server berkala.', 'Mulai Dari', 'Rp 990.000', '990000', '/ bulan', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=800&q=80', 'Jaga kestabilan dan keamanan aplikasi bisnis Anda tanpa perlu khawatir server down. Layanan DevOps dan managed server profesional untuk skalabilitas bisnis tinggi.', '[\"Setup Cloud VPS \\/ Server AWS GCP\",\"Automasi Deployment CI\\/CD\",\"Backup Database Otomatis Harian\",\"Monitoring Server 24\\/7 Uptime\"]', '[\"Firewall & Hardening Security\",\"SSL Certificate Management\",\"Laporan Performa Bulanan\"]', '[\"Docker & Kubernetes Containerization\",\"Load Balancer Configuration\",\"Penanganan Insiden Darurat (SLA Fast Response)\"]', 'Halo Elcoding, saya butuh layanan Cloud Server & DevOps Maintenance.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
INSERT INTO `layanans` (`id`, `title`, `slug`, `icon`, `badge`, `short_description`, `price_label`, `price`, `price_amount`, `price_period`, `image_path`, `description`, `features_main`, `pricing_includes`, `features_full`, `whatsapp_message`, `created_at`, `updated_at`) VALUES ('6', 'Audit Keamanan Website & PenTest', 'audit-keamanan-website-penetration-testing', 'fas fa-shield-alt', 'BARU', 'Pengujian penetrasi (Penetration Testing) dan analisis celah keamanan website serta server aplikasi dari potensi peretasan.', 'Mulai Dari', 'Rp 1.950.000', '1950000', '/ audit', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?auto=format&fit=crop&w=800&q=80', 'Lindungi data sensitif pelanggan dan reputasi bisnis Anda dari ancaman cyber crime, SQL injection, XSS, dan kebocoran data dengan pengujian keamanan standar OWASP.', '[\"Vulnerability Assessment OWASP Top 10\",\"Penetration Testing Blackbox & Graybox\",\"Laporan Rekomendasi Perbaikan\",\"Re-Testing Setelah Fix Celah\"]', '[\"Dokumen Executive Summary Audit\",\"Panduan Remediasi Teknis\",\"Sertifikat Audit Keamanan\"]', '[\"Pemeriksaan Security Header & Network Port\",\"Analisis Kerentanan API Endpoint\",\"Konsultasi Tim Security Specialist\"]', 'Halo Elcoding, saya ingin berkonsultasi untuk Audit Keamanan Website / PenTest.', '2026-09-07 03:00:06', '2026-09-07 03:00:06');
